import hashlib,json
m=json.load(open('artifacts/NC-022/checkpoint_manifest.json'))
def H(p):
 h=hashlib.sha256()
 with open(p,'rb') as f:
  for b in iter(lambda:f.read(1<<20),b''): h.update(b)
 return h.hexdigest()
errs=[]
for x in m['checkpoints']:
 for kind,p,want in [('checkpoint',x['path'],x['sha256']),('evaluation',x['evaluation_trace']['path'],x['evaluation_trace']['sha256'])]:
  got=H(p)
  if got"'!=want: errs.append([kind,p,want,got])
print(json.dumps({'"'checkpoints_hashed':len(m['checkpoints']),'evaluations_hashed':len(m['checkpoints']),'hash_mismatches':errs},indent=2))
paths={'protocol':'artifacts/NC-022/PROTOCOL.json','experiment':'artifacts/NC-022/rlt_rehearsal.py','architecture':'/workspace/experiments/rlt_split_algorithms_ablation_v1/task_conditioned_rlt.py','backbone':'/workspace/experiments/rlt_split_algorithms_ablation_v1/rlt_core.py','snapshot':'/workspace/experiments/rlt_split_algorithms_ablation_v1/snapshots/current_unified_v3.pt','inventory':'artifacts/NC-000/inventory.json'}
for label,p in paths.items():
 got=H(p); want=m['source_sha256'][label]; print(label,got,'OK' if got==want else 'MISMATCH')
for label,p,key in [('retention','artifacts/NC-022/rlt_retention_matrix.json','retention_matrix_sha256'),('ablation','artifacts/NC-022/exposure_matched_ablation.json','exposure_matched_ablation_sha256'),('ledger','artifacts/NC-022/train_and_holdout_ledger.json','train_ledger_sha256')]:
 got=H(p); print(label,got,'OK' if got==m[key] else 'MISMATCH')
r=json.load(open('artifacts/NC-022/independent_receipt.json'))
for label,p,key in [('verifier_final',r['raw_verifier_final_file'],'raw_verifier_final_sha256'),('verifier_trace',r['raw_verifier_trace_file'],'raw_verifier_trace_sha256')]:
 got=H(p); print(label,got,'OK' if got==r[key] else 'MISMATCH')
